CREATE TABLE `legal_documents` (`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,`slug` text NOT NULL,`title` text NOT NULL,`version` text NOT NULL,`content` text NOT NULL,`published` integer DEFAULT false NOT NULL,`valid_from` text,`updated_at` text DEFAULT 'CURRENT_TIMESTAMP' NOT NULL);
CREATE UNIQUE INDEX `legal_documents_slug_unique` ON `legal_documents` (`slug`);
CREATE TABLE `consent_records` (`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,`request_id` integer,`subject_ref` text NOT NULL,`purpose` text NOT NULL,`granted` integer NOT NULL,`document_slug` text NOT NULL,`document_version` text NOT NULL,`source` text NOT NULL,`created_at` text DEFAULT 'CURRENT_TIMESTAMP' NOT NULL,`revoked_at` text,FOREIGN KEY (`request_id`) REFERENCES `valuation_requests`(`id`));
CREATE TABLE `notification_events` (`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,`type` text NOT NULL,`reference_type` text NOT NULL,`reference_id` text NOT NULL,`payload` text NOT NULL,`dedupe_key` text NOT NULL,`created_at` text DEFAULT 'CURRENT_TIMESTAMP' NOT NULL);
CREATE UNIQUE INDEX `notification_events_dedupe_key_unique` ON `notification_events` (`dedupe_key`);
CREATE TABLE `notification_deliveries` (`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,`event_id` integer NOT NULL,`channel` text NOT NULL,`destination` text,`status` text DEFAULT 'pending' NOT NULL,`attempt_count` integer DEFAULT 0 NOT NULL,`next_attempt_at` text,`provider_message_id` text,`last_error` text,`read_at` text,`created_at` text DEFAULT 'CURRENT_TIMESTAMP' NOT NULL,`updated_at` text DEFAULT 'CURRENT_TIMESTAMP' NOT NULL,FOREIGN KEY (`event_id`) REFERENCES `notification_events`(`id`));
CREATE TABLE `appointment_settings` (`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,`weekday` integer NOT NULL,`start_time` text NOT NULL,`end_time` text NOT NULL,`slot_minutes` integer DEFAULT 60 NOT NULL,`active` integer DEFAULT true NOT NULL);
CREATE TABLE `appointment_closed_days` (`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,`date` text NOT NULL,`reason` text,`created_at` text DEFAULT 'CURRENT_TIMESTAMP' NOT NULL);
CREATE UNIQUE INDEX `appointment_closed_days_date_unique` ON `appointment_closed_days` (`date`);
CREATE TABLE `appointment_bookings` (`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,`request_id` integer NOT NULL,`start_at` text NOT NULL,`end_at` text NOT NULL,`timezone` text DEFAULT 'Europe/Istanbul' NOT NULL,`status` text DEFAULT 'requested' NOT NULL,`created_at` text DEFAULT 'CURRENT_TIMESTAMP' NOT NULL,`updated_at` text DEFAULT 'CURRENT_TIMESTAMP' NOT NULL,`cancelled_at` text,FOREIGN KEY (`request_id`) REFERENCES `valuation_requests`(`id`));
CREATE UNIQUE INDEX `appointment_bookings_start_at_unique` ON `appointment_bookings` (`start_at`);
CREATE TABLE `appointment_history` (`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,`booking_id` integer NOT NULL,`from_status` text,`to_status` text NOT NULL,`actor_type` text NOT NULL,`note` text,`created_at` text DEFAULT 'CURRENT_TIMESTAMP' NOT NULL,FOREIGN KEY (`booking_id`) REFERENCES `appointment_bookings`(`id`));
CREATE TABLE `admin_users` (`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,`email` text NOT NULL,`password_hash` text NOT NULL,`role` text DEFAULT 'staff' NOT NULL,`active` integer DEFAULT true NOT NULL,`created_at` text DEFAULT 'CURRENT_TIMESTAMP' NOT NULL,`last_login_at` text);
CREATE UNIQUE INDEX `admin_users_email_unique` ON `admin_users` (`email`);
CREATE TABLE `admin_sessions` (`id` text PRIMARY KEY NOT NULL,`admin_user_id` integer,`role` text NOT NULL,`expires_at` text NOT NULL,`created_at` text DEFAULT 'CURRENT_TIMESTAMP' NOT NULL,FOREIGN KEY (`admin_user_id`) REFERENCES `admin_users`(`id`));
CREATE TABLE `audit_logs` (`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,`actor_id` text NOT NULL,`actor_role` text NOT NULL,`action` text NOT NULL,`target_type` text NOT NULL,`target_id` text,`metadata` text NOT NULL,`created_at` text DEFAULT 'CURRENT_TIMESTAMP' NOT NULL);
CREATE TABLE `otp_challenges` (`id` text PRIMARY KEY NOT NULL,`phone_hash` text NOT NULL,`code_hash` text NOT NULL,`purpose` text NOT NULL,`expires_at` text NOT NULL,`attempt_count` integer DEFAULT 0 NOT NULL,`consumed_at` text,`created_at` text DEFAULT 'CURRENT_TIMESTAMP' NOT NULL);
CREATE TABLE `rate_limit_buckets` (`key` text PRIMARY KEY NOT NULL,`window_start` integer NOT NULL,`count` integer DEFAULT 0 NOT NULL);
CREATE TABLE `vehicle_price_analyses` (`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,`request_id` integer,`input` text NOT NULL,`result` text NOT NULL,`data_source` text NOT NULL,`confidence` text NOT NULL,`created_at` text DEFAULT 'CURRENT_TIMESTAMP' NOT NULL,FOREIGN KEY (`request_id`) REFERENCES `valuation_requests`(`id`));
CREATE TABLE `vehicle_market_comparables` (`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,`brand` text NOT NULL,`model` text NOT NULL,`year` integer NOT NULL,`mileage` integer NOT NULL,`price` integer NOT NULL,`fuel_type` text,`transmission` text,`trim` text,`source_name` text NOT NULL,`source_record_id` text NOT NULL,`observed_at` text NOT NULL,`licensed` integer DEFAULT false NOT NULL,`active` integer DEFAULT true NOT NULL);
CREATE UNIQUE INDEX `vehicle_market_comparables_source_record_id_unique` ON `vehicle_market_comparables` (`source_record_id`);
